     "summary": "无论是程女士处方上的可瑞达，还是上述司法案例中的贝林妥欧单抗，都是治疗癌症等重大疾病的特效药。它们价格高昂，多数未“进入”医院药房，需要医生开处方，患者到院外自购。如果想要商业保险公司支付相关药物的费用，需要患者购买带有“特药责任”的医疗险。随着特药适应症扩容，理赔纠纷不断增加，超适应症用药是拒赔的常见理由之一。",
